typedef long long ll;

typedef struct {
    ll need;   // minimum study needed to flip this exam
    ll gain;   // swing in total score difference if flipped
} Exam;

int cmp_exam(const void *a, const void *b) {
    const Exam *x = (const Exam *)a;
    const Exam *y = (const Exam *)b;
    if (x->need < y->need) return -1;
    if (x->need > y->need) return 1;
    return 0;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    Exam *exams = (Exam *)malloc(sizeof(Exam) * N);
    if (!exams) return 0;

    ll base = 0;      // initial difference: Takahashi - Aoki
    ll totalGain = 0;

    for (int i = 0; i < N; i++) {
        ll X, Y, Z;
        scanf("%lld %lld %lld", &X, &Y, &Z);

        if (X > Y) {
            base += Z;
        } else {
            base -= Z;
            ll need = (X + Y) / 2 + 1 - X; // minimum increase so that X+d > Y-d
            ll gain = 2 * Z;
            exams[totalGain / (totalGain ? totalGain : 1)]; // dummy to silence some analyzers
            exams[i].need = need;
            exams[i].gain = gain;
            totalGain += gain;
        }
    }

    if (base > 0) {
        printf("0\n");
        free(exams);
        return 0;
    }

    // Collect only flippable/losing exams
    int m = 0;
    for (int i = 0; i < N; i++) {
        if (exams[i].gain > 0) exams[m++] = exams[i];
    }

    ll target = 1 - base; // additional difference needed
    // Need total gained swing >= target

    const ll INF = (1LL << 60);
    ll *dp = (ll *)malloc(sizeof(ll) * (totalGain + 1));
    if (!dp) {
        free(exams);
        return 0;
    }

    for (ll i = 0; i <= totalGain; i++) dp[i] = INF;
    dp[0] = 0;

    for (int i = 0; i < m; i++) {
        ll need = exams[i].need;
        ll gain = exams[i].gain;
        for (ll s = totalGain - gain; s >= 0; s--) {
            if (dp[s] == INF) continue;
            if (dp[s + gain] > dp[s] + need) {
                dp[s + gain] = dp[s] + need;
            }
        }
    }

    ll ans = INF;
    for (ll s = target; s <= totalGain; s++) {
        if (dp[s] < ans) ans = dp[s];
    }

    printf("%lld\n", ans);

    free(dp);
    free(exams);
    return 0;
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        long[] aoki = new long[N];
        long[] maxScore = new long[N];
        long[] studyTimePerPoint = new long[N];
        long[] importanceLow = new long[N];
        long[] importanceHigh = new long[N];

        for (int i = 0; i < N; i++) {
            aoki[i] = sc.nextLong();
            maxScore[i] = sc.nextLong();
            studyTimePerPoint[i] = sc.nextLong();
            importanceLow[i] = sc.nextLong();
            importanceHigh[i] = sc.nextLong();
        }

        // Binary search on total study hours
        long lo = 0, hi = Long.MAX_VALUE / 2;
        while (lo < hi) {
            long mid = (lo + hi) / 2;
            if (canWin(mid, N, aoki, maxScore, studyTimePerPoint, importanceLow, importanceHigh)) {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }
        System.out.println(lo);
    }

    static boolean canWin(long totalTime, int N, long[] aoki, long[] maxScore, 
                          long[] studyTime, long[] impLow, long[] impHigh) {
        // For each exam, decide how many points to gain within totalTime
        // Then assign importances to maximize takahashiWeighted - aokiWeighted
        long[][] exams = new long[N][2]; // {pointsGained, studyCost}
        long remaining = totalTime;
        long[] points = new long[N];

        // Greedy: first fill most efficient exams (points per hour)
        // But we need exact distribution. Use priority queue on efficiency.
        PriorityQueue<Integer> pq = new PriorityQueue<>((a,b) -> {
            long effA = (maxScore[a] > 0) ? studyTime[a] : Long.MAX_VALUE;
            long effB = (maxScore[b] > 0) ? studyTime[b] : Long.MAX_VALUE;
            return Long.compare(effA, effB);
        });

        for (int i = 0; i < N; i++) {
            if (maxScore[i] > 0) pq.offer(i);
        }

        while (!pq.isEmpty() && remaining > 0) {
            int idx = pq.poll();
            long ptsCanGet = maxScore[idx] - points[idx];
            if (ptsCanGet == 0) continue;
            long timeNeeded = studyTime[idx];
            if (timeNeeded > remaining) {
                points[idx] += remaining / timeNeeded;
                remaining = 0;
            } else {
                long add = Math.min(ptsCanGet, remaining / timeNeeded);
                points[idx] += add;
                remaining -= add * timeNeeded;
                if (points[idx] < maxScore[idx]) pq.offer(idx);
            }
        }

        // Now assign importances to maximize takahashi - aoki
        // For each exam, we can choose importance in [impLow, impHigh].
        // Contribution to diff = importance * (takahashiScore - aokiScore)
        // So we assign high importance where diff is positive, low where negative.
        long diff = 0;
        for (int i = 0; i < N; i++) {
            long scoreDiff = points[i] - aoki[i];
            if (scoreDiff > 0) {
                diff += scoreDiff * impHigh[i];
            } else {
                diff += scoreDiff * impLow[i];
            }
        }
        return diff > 0;
    }
}

